	/** Whether a glyph of this name is bundled. */
	public static function has( $name ) {
		return isset( self::PATHS[ (string) $name ] );
	}

	/** Every bundled glyph name. Used by the test that keeps callers honest. */
	public static function names() {
		return array_keys( self::PATHS );
	}

	/**
	 * One glyph, as an <svg> string ready to echo.
	 *
	 * @param string $name  A key of ::PATHS, e.g. `shield-check`.
	 * @param array  $args  {
	 *     @type int    $size  Edge length in px. Default ::SIZE.
	 *     @type string $class Extra class on the <svg>.
	 *     @type string $label Accessible name. Omit for decorative icons —
	 *                         see the header for why that is the default.
	 * }
	 * @return string The markup, or '' when the name is unknown.
	 */
	public static function svg( $name, $args = array() ) {
		$name = (string) $name;
		if ( ! isset( self::PATHS[ $name ] ) ) {
			/*
			 * An unknown name is a typo at the call site and paints nothing, so
			 * it fails the way a missing icon always does — silently, on
			 * someone else's screen. Say so on a developer's install; the icon
			 * test catches it before that.
			 */
			if ( function_exists( '_doing_it_wrong' ) ) {
				_doing_it_wrong(
					__METHOD__,
					esc_html( sprintf( 'Unknown icon "%s".', $name ) ),
					defined( 'AISOOQ_VERSION' ) ? AISOOQ_VERSION : '0.0.0'
				);
			}
			return '';
		}

		$args  = is_array( $args ) ? $args : array();
		$size  = isset( $args['size'] ) ? max( 1, (int) $args['size'] ) : self::SIZE;
		$class = isset( $args['class'] ) ? trim( 'aisooq-i ' . $args['class'] ) : 'aisooq-i';
		$label = isset( $args['label'] ) ? trim( (string) $args['label'] ) : '';

		// A named icon is announced; an unnamed one is furniture. Never both.
		$a11y = '' !== $label
			? ' role="img" aria-label="' . esc_attr( $label ) . '"'
			: ' aria-hidden="true" focusable="false"';

		return '<svg class="' . esc_attr( $class ) . '"'
			. ' width="' . (int) $size . '" height="' . (int) $size . '"'
			. ' viewBox="' . esc_attr( self::VIEWBOX ) . '"'
			. ' fill="currentColor"' . $a11y . '>'
			. '<path d="' . esc_attr( self::PATHS[ $name ] ) . '"/>'
			. '</svg>';
	}
}
